-- Self-contained SQL row/relationship tests. Requires schema 001-030 and identity seeds 101-103.
-- No service/RBAC/Kafka publication claim: API atomicity remains the component suite's responsibility.
-- Fixed synthetic rows are rolled back; existing lifecycle rows are never updated.
SET time_zone='+00:00';
DROP PROCEDURE IF EXISTS processing_assert;
DROP PROCEDURE IF EXISTS processing_reject;
DROP PROCEDURE IF EXISTS processing_finish;
DROP TEMPORARY TABLE IF EXISTS processing_checks;
CREATE TEMPORARY TABLE processing_checks(name VARCHAR(128),result VARCHAR(4),detail VARCHAR(2048)) ENGINE=MEMORY;
DELIMITER $$
CREATE PROCEDURE processing_assert(IN n VARCHAR(128),IN ok BOOLEAN)
BEGIN
 INSERT INTO processing_checks VALUES(n,IF(COALESCE(ok,FALSE),'PASS','FAIL'),'expected TRUE');
END$$
CREATE PROCEDURE processing_reject(IN n VARCHAR(128),IN statement_text TEXT,IN expected_errno INT,IN constraint_name VARCHAR(128))
BEGIN
 DECLARE error_number INT DEFAULT 0;
 DECLARE error_message TEXT DEFAULT '';
 DECLARE prepared BOOLEAN DEFAULT FALSE;
 SAVEPOINT rejected_record;
 BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
   GET DIAGNOSTICS CONDITION 1 error_number=MYSQL_ERRNO,error_message=MESSAGE_TEXT;
  SET @processing_statement=statement_text;
  PREPARE processing_stmt FROM @processing_statement;
  SET prepared=TRUE;
  EXECUTE processing_stmt;
 END;
 IF prepared THEN DEALLOCATE PREPARE processing_stmt; END IF;
 ROLLBACK TO SAVEPOINT rejected_record;
 INSERT INTO processing_checks VALUES(n,
   IF(error_number=expected_errno AND LOCATE(constraint_name,error_message)>0,'PASS','FAIL'),
   CONCAT(error_number,': ',error_message));
END$$
CREATE PROCEDURE processing_finish()
BEGIN
 SELECT name,result,detail FROM processing_checks ORDER BY name;
 IF EXISTS(SELECT 1 FROM processing_checks WHERE result='FAIL') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Processing fixture checks failed';
 END IF;
END$$
DELIMITER ;
START TRANSACTION;
